#[derive(Debug, Clone, PartialEq)]
pub struct Bot {
    pub id: i64,
    pub user_id: i64,
    pub creator_id: i64,
    pub code: String,
    pub created_at: Timestamp,
    pub updated_at: Timestamp,
}

columns! {
