use crate::tests::{TestDb, id};

#[test]
fn bot_crud_and_queries() {
    let t = TestDb::new();
    let creator_id = id("david");

    // Create user for bot
    let bot_user = t.write(|tx| {
        User::create(
            tx,
            NewUser {
                name: "Deploy Bot".into(),
                password_digest: PasswordDigest::create("dummy", 4).ok(),
                role: Role::Member,
                ..Default::default()
            },
        )
    });

    // Create bot
    let code = Bot::generate_code();
    let bot_user_id = bot_user.id;
    let code_clone = code.clone();
    let bot = t.write(move |tx| Bot::create(tx, bot_user_id, creator_id, &code_clone));
    assert_eq!(bot.user_id, bot_user.id);
    assert_eq!(bot.creator_id, creator_id);
    assert_eq!(bot.code, code);

    // Finders
    let bot_id = bot.id;
    let found = t.read(move |c| Bot::find(c, bot_id));
    assert_eq!(found, bot);

    let code_clone = code.clone();
    let found_by_code = t.read(move |c| Bot::find_by_code(c, &code_clone)).unwrap();
    assert_eq!(found_by_code, bot);

    let found_by_user = t.read(move |c| Bot::find_by_user_id(c, bot_user.id)).unwrap();
    assert_eq!(found_by_user, bot);

    let bots = t.read(move |c| Bot::for_creator(c, creator_id));
    assert!(bots.iter().any(|b| b.id == bot.id));

    let all = t.read(Bot::all);
    assert!(all.iter().any(|b| b.id == bot.id));

    // Destroy
    let bot_clone = bot.clone();
    t.write(move |tx| bot_clone.destroy(tx));
    assert!(t.read(move |c| Bot::find_by_id(c, bot_id)).is_none());
    assert!(t.read(move |c| Bot::find_by_code(c, &code)).is_none());
}
"
}

