use campfire_db::{Bot, Membership, Message, NewMessage, Room, Status, User};
use campfire_kit::{Ctx, Result, StatusCode};
use ruby_compat::integer_cast;

use crate::app::AppCtx;
use crate::concerns::{self, Authentication, Before};
use crate::controllers::messages;

/// `POST /rooms/:room_id/:bot_code/messages`
pub async fn create(c: &mut Ctx) -> Result {
    concerns::before_actions(
        c,
        Before {
            authentication: Authentication::Skipped,
            forgery_protection: false,
        },
    )
    .await?;

    let Some(bot_code) = c.param_str("bot_code") else {
        return Ok(c.head(StatusCode::UNAUTHORIZED));
    };
    let bot_code = bot_code.to_string();

    // 1. Authenticate bot
    let bot_and_user = c
        .app()
        .read(move |conn| {
            let Some(bot) = Bot::find_by_code(conn, &bot_code)? else {
                return Ok(None);
            };
            let Some(bot_user) = User::find_by_id(conn, bot.user_id)? else {
                return Ok(None);
            };
            if bot_user.status != Status::Active {
                return Ok(None);
            }
            Ok(Some((bot, bot_user)))
        })
        .await?;

    let Some((bot, _)) = bot_and_user else {
        return Ok(c.head(StatusCode::UNAUTHORIZED));
    };

    // 2. Validate room & membership
    let Some(room_id) = c.param_str("room_id").and_then(integer_cast) else {
        return Ok(c.head(StatusCode::NOT_FOUND));
    };
    let bot_user_id = bot.user_id;

    let room = c
        .app()
        .read(move |conn| {
            let Some(room) = Room::find_by_id(conn, room_id)? else {
                return Ok(None);
            };
            let membership = Membership::find_by_room_and_user(conn, room_id, bot_user_id)?;
            if membership.is_none() {
                return Ok(None);
            }
            Ok(Some(room))
        })
        .await?;

    let Some(room) = room else {
        return Ok(c.head(StatusCode::NOT_FOUND));
    };

    // 3. Validate body
    let raw = c.request.raw_post();
    let body_text = String::from_utf8_lossy(raw).to_string();
    if body_text.trim().is_empty() {
        return Ok(c.head(StatusCode::UNPROCESSABLE_ENTITY));
    }

    // 4. Canonicalize body and create message
    let canonical_body = messages::canonicalize_body(c.app(), body_text, Some(c.request.host())).await?;
    let bot_user_id = bot.user_id;
    let room_id = room.id;

    let message = c
        .app()
        .write(move |tx| {
            Message::create(
                tx,
                NewMessage {
                    room_id,
                    creator_id: bot_user_id,
                    client_message_id: None,
                    body: Some(canonical_body),
                    attachment_blob_id: None,
                },
            )
        })
        .await?;

    // 5. Broadcast message
    messages::broadcast_create(c, &room, &message).await?;

    let location = format!("/messages/{}", message.id);
    Ok(c.head(StatusCode::CREATED).header(axum::http::header::LOCATION, &location))
}
