pub mod messages;

use campfire_db::{Bot, NewUser, PasswordDigest, Role, Status, User, UserChanges};
use campfire_kit::params::Permit;
use campfire_kit::{Ctx, Error, Param, Redirect, Result, StatusCode, format, halt};
use campfire_views::bots as views;
use ruby_compat::integer_cast;

use crate::app::AppCtx;
use crate::concerns::{self, Before, require_current_user};
use crate::controllers::presenters;
use crate::controllers::presenters::attachments::{self, Assignment, Record};
use crate::controllers::presenters::page;

/// `GET /bots`
pub async fn index(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let current_user = require_current_user(c)?.clone();
    c.respond_to(&[&format::HTML])?;

    let secrets = c.app().secrets.clone();
    let is_admin = current_user.is_administrator();
    let user_id = current_user.id;

    let bot_views = c
        .app()
        .read_offloaded(move |conn| {
            let bots = if is_admin {
                Bot::all(conn)?
            } else {
                Bot::for_creator(conn, user_id)?
            };
            let mut list = Vec::new();
            for bot in bots {
                if let Ok(Some(bot_user)) = User::find_by_id(conn, bot.user_id) {
                    if bot_user.status == Status::Active {
                        list.push(views::BotView {
                            id: bot.id,
                            name: bot_user.name.clone(),
                            code: bot.code,
                            avatar_url: presenters::avatar_path(&secrets, &bot_user),
                        });
                    }
                }
            }
            Ok(list)
        })
        .await?;

    page::framed_page!(c, StatusCode::OK, |ctx| views::Index { ctx, bots: bot_views.clone() }).await
}

/// `GET /bots/new`
pub async fn new(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    require_current_user(c)?;
    c.respond_to(&[&format::HTML])?;
    page::framed_page!(c, StatusCode::OK, |ctx| views::New { ctx }).await
}

/// `POST /bots`
pub async fn create(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let current_user = require_current_user(c)?.clone();

    let params = c.params.require("bot")?.permit(&[Permit::from("name"), Permit::from("avatar")]);
    let Some(name) = params.get("name").and_then(Param::to_s).map(|s| s.trim().to_string()).filter(|s| !s.is_empty()) else {
        return halt(concerns::head(StatusCode::UNPROCESSABLE_ENTITY));
    };

    let avatar = Assignment::from_params(&params, "avatar")?.stage(c.app()).await?;
    let code = Bot::generate_code();
    let creator_id = current_user.id;

    let pending = c
        .app()
        .write(move |tx| {
            let password_digest = PasswordDigest::create(&sql_random_pass(), 4).ok();
            let bot_user = User::create(
                tx,
                NewUser {
                    name,
                    password_digest,
                    role: Role::Member,
                    ..Default::default()
                },
            )?;
            let bot = Bot::create(tx, bot_user.id, creator_id, &code)?;
            let pending = attachments::assign(tx, Record::user(bot_user.id), "avatar", avatar)?;
            Ok((bot, pending))
        })
        .await?;

    let (_, pending_attachment) = pending;
    attachments::analyze_later(c.app(), pending_attachment);

    let location = c.url_for(&campfire_routes::bots());
    c.redirect_to_with(&location, Redirect { notice: Some("✓".into()), ..Redirect::default() })
}

/// `GET /bots/:id/edit`
pub async fn edit(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let current_user = require_current_user(c)?.clone();
    let bot_id = set_bot_id(c)?;
    c.respond_to(&[&format::HTML])?;

    let secrets = c.app().secrets.clone();
    let (bot, bot_user) = c
        .app()
        .read(move |conn| {
            let bot = Bot::find(conn, bot_id)?;
            let user = User::find(conn, bot.user_id)?;
            Ok((bot, user))
        })
        .await?;

    if !current_user.can_administer(Some(bot.creator_id), false) {
        return halt(concerns::head(StatusCode::FORBIDDEN));
    }

    let bot_view = views::BotView {
        id: bot.id,
        name: bot_user.name.clone(),
        code: bot.code,
        avatar_url: presenters::avatar_path(&secrets, &bot_user),
    };

    page::framed_page!(c, StatusCode::OK, |ctx| views::Edit { ctx, bot: bot_view.clone() }).await
}

/// `PATCH/PUT /bots/:id`
pub async fn update(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let current_user = require_current_user(c)?.clone();
    let bot_id = set_bot_id(c)?;

    let (bot, mut bot_user) = c
        .app()
        .read(move |conn| {
            let bot = Bot::find(conn, bot_id)?;
            let user = User::find(conn, bot.user_id)?;
            Ok((bot, user))
        })
        .await?;

    if !current_user.can_administer(Some(bot.creator_id), false) {
        return halt(concerns::head(StatusCode::FORBIDDEN));
    }

    let params = c.params.require("bot")?.permit(&[Permit::from("name"), Permit::from("avatar")]);
    let name = params.get("name").and_then(Param::to_s).map(|s| s.trim().to_string()).filter(|s| !s.is_empty());
    let avatar = match Assignment::from_params(&params, "avatar")? {
        Assignment::Delete if params.get("avatar").is_none_or(|p| p.is_null()) => Assignment::Unchanged,
        assignment => assignment,
    };
    let avatar = avatar.stage(c.app()).await?;

    let pending = c
        .app()
        .write(move |tx| {
            if let Some(new_name) = name {
                bot_user.update(tx, UserChanges { name: Some(new_name), ..UserChanges::default() })?;
            }
            attachments::assign(tx, Record::user(bot_user.id), "avatar", avatar)
        })
        .await?;
    attachments::analyze_later(c.app(), pending);

    let location = c.url_for(&campfire_routes::bots());
    c.redirect_to_with(&location, Redirect { notice: Some("✓".into()), ..Redirect::default() })
}

/// `DELETE /bots/:id`
pub async fn destroy(c: &mut Ctx) -> Result {
    concerns::before_actions(c, Before::default()).await?;
    let current_user = require_current_user(c)?.clone();
    let bot_id = set_bot_id(c)?;

    let (bot, mut bot_user) = c
        .app()
        .read(move |conn| {
            let bot = Bot::find(conn, bot_id)?;
            let user = User::find(conn, bot.user_id)?;
            Ok((bot, user))
        })
        .await?;

    if !current_user.can_administer(Some(bot.creator_id), false) {
        return halt(concerns::head(StatusCode::FORBIDDEN));
    }

    c.app()
        .write(move |tx| {
            bot.destroy(tx)?;
            bot_user.deactivate(tx)?;
            Ok(())
        })
        .await?;

    let location = c.url_for(&campfire_routes::bots());
    c.redirect_to(&location)
}

fn set_bot_id(c: &Ctx) -> Result<i64> {
    c.param_str("id").and_then(integer_cast).ok_or(Error::NotFound)
}

fn sql_random_pass() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    format!("bot-pass-{}", SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos())
}

#[cfg(test)]
mod tests;
"
}

