        r#"<div><action-text-attachment sgid="{sgid}" content-type="application/vnd.campfire.mention" content="{}"></action-text-attachment> run deployment</div>"#,
        bot_user.name
    );

    david
        .send(
            Req::new(Method::POST, &format!("/rooms/{HQ}/messages"))
                .header("accept", "text/vnd.turbo-stream.html")
                .form(&[("message[body]", &mention_html)]),
        )
        .await;

    let payload = tokio::time::timeout(std::time::Duration::from_secs(5), rx_payload)
        .await
        .expect("webhook received")
        .expect("channel open");

    assert_eq!(payload["event"], "mention");
    assert_eq!(payload["message"]["body"]["text"], "run deployment");

    // Verify HTML reply was posted
    let mut reply_posted = false;
    for _ in 0..50 {
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        let messages = app.db().read(|conn| Message::last_page(conn, HQ)).await.unwrap();
        if messages.iter().any(|m| m.creator_id == bot.user_id) {
            reply_posted = true;
            let msg = messages.iter().find(|m| m.creator_id == bot.user_id).unwrap();
            let rich_text = app.booted.app.db.env().rich_text.clone();
            let text = app.db().read({
                let msg = msg.clone();
                move |conn| msg.plain_text_body(conn, &*rich_text)
            }).await.unwrap();
            assert!(text.contains("Deploy complete"));
            break;
        }
    }
    assert!(reply_posted, "html bot's reply should be posted");
}

#[tokio::test]
async fn bot_async_reply_via_reply_to() {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;
    use tokio::sync::oneshot;

    let app = TestApp::boot().await;
    let mut david = app.david();

    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let (tx_payload, rx_payload) = oneshot::channel::<serde_json::Value>();

    tokio::spawn(async move {
        if let Ok((mut stream, _)) = listener.accept().await {
            let mut buf = vec![0u8; 8192];
            let n = stream.read(&mut buf).await.unwrap();
            let req_str = String::from_utf8_lossy(&buf[..n]).to_string();

            if let Some(pos) = req_str.find("\r\n\r\n") {
                let body = &req_str[pos + 4..];
                if let Ok(json) = serde_json::from_str::<serde_json::Value>(body) {
                    let _ = tx_payload.send(json);
                }
            }

            // Return 204 No Content for the synchronous response
            let response = "HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n";
            let _ = stream.write_all(response.as_bytes()).await;
        }
    });

    let webhook_url = format!("http://127.0.0.1:{port}/webhook");
    david.send(Req::new(Method::POST, "/bots").form(&[("bot[name]", "Async Bot"), ("bot[webhook_url]", &webhook_url)])).await;

    let bot = app.db().read(|conn| {
        let bots = Bot::all(conn)?;
        Ok(bots.into_iter().find(|b| b.webhook_url.is_some()).unwrap())
    }).await.unwrap();

    david
        .send(
            Req::new(Method::POST, &format!("/rooms/{HQ}/messages"))
                .header("accept", "text/vnd.turbo-stream.html")
                .form(&[("message[body]", "@Async Bot run background task")]),
        )
        .await;

    let payload = tokio::time::timeout(std::time::Duration::from_secs(5), rx_payload)
        .await
        .expect("webhook received")
        .expect("channel open");

    let reply_to = payload["room"]["reply_to"].as_str().expect("reply_to string");
    assert_eq!(reply_to, format!("/rooms/{HQ}/{}/messages", bot.code));

    // Now bot replies asynchronously by posting to reply_to
    let mut async_client = app.anonymous();
    let mut req = Req::new(Method::POST, reply_to);
    req.body = b"Finished background task out-of-band!".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = async_client.send(req).await;
    assert_eq!(reply.status, StatusCode::CREATED);

    // Verify message appears in room
    let messages = app.db().read(|conn| Message::last_page(conn, HQ)).await.unwrap();
    let msg = messages.iter().find(|m| m.creator_id == bot.user_id).expect("async message exists");
    let rich_text = app.booted.app.db.env().rich_text.clone();
    let text = app.db().read({
        let msg = msg.clone();
        move |conn| msg.plain_text_body(conn, &*rich_text)
    }).await.unwrap();
    assert!(text.contains("Finished background task out-of-band!"));
}
